sub merge_sort_descending {
    my @arr = @_;
    my $len = scalar(@arr);
    if ($len <= 1) {
        return @arr;
    }
    my $mid = int($len/2);
    my @L = merge_sort_descending(@arr[0..($mid-1)]);
    my @R = merge_sort_descending(@arr[$mid..($len-1)]);
    my @result = ();
    while (@L && @R) {
        if ($L[0] >= $R[0]) {
            push(@result, shift(@L));
        } else {
            push(@result, shift(@R));
        }
    }
    push(@result, @L);
    push(@result, @R);
    return @result;
}
