Here's an implementation of a singly linked list in C++ with the mentioned functions. To ensure data integrity and modularity, the class is encapsulated with private data members that can only be accessed through public member functions.

```c++
#include<iostream>

using namespace std;

//Definition of a node
struct Node {
    int data; //Data stored in the node
    Node* next; //Pointer to the next node in the list

    //Constructor
    Node(int val) {
        data = val;
        next = nullptr;
    }
};

//Definition of the linked list class
class LinkedList {
    //Private data members
    private:
        Node* head; //Pointer to the start of the list
        int size; //Size of the list
    //Public member functions
    public:
        //Constructor
        LinkedList() {
            head = nullptr;
            size = 0;
        }

        //Insert a node at the beginning of the list
        void insertAtBeginning(int val) {
            Node* newNode = new Node(val);
            if(head == nullptr) {
                head = newNode; //List is empty
            }
            else {
                newNode->next = head;
                head = newNode;
            }
            size++;
        }

        //Insert a node at the end of the list
        void insertAtEnd(int val) {
            Node* newNode = new Node(val);
            Node* temp = head;
            if(head == nullptr) {
                head = newNode; //List is empty
            }
            else {
                while(temp->next != nullptr) {
                    temp = temp->next;
                }
                temp->next = newNode;
            }
            size++;
        }

        //Insert a node at a specific position in the list
        void insertAtPosition(int val, int pos) {
            Node* newNode = new Node(val);
            Node* temp = head;
            if(pos == 0 || head == nullptr) {
                insertAtBeginning(val); //Insert at beginning
            }
            else if(pos == size) {
                insertAtEnd(val); //Insert at end
            }
            else if(pos < size) {
                for(int I = 0; I < pos-1; i++) {
                    temp = temp->next;
                }
                newNode->next = temp->next;
                temp->next = newNode;
                size++;
            }
            else {
                cout << "Invalid position!" << endl;
            }
        }

        //Delete a node from the list
        void deleteNode(int val) {
            Node* temp = head;
            Node* prev = nullptr;
            while(temp != nullptr && temp->data != val) {
                prev = temp;
                temp = temp->next;
            }
            if(temp == nullptr) {
                cout << "Node not found!" << endl;
            }
            else if(temp == head) {
                head = head->next;
                delete temp;
                size--;
            }
            else {
                prev->next = temp->next;
                delete temp;
                size--;
            }
        }

        //Traverse the entire list and display its contents
        void traverseList() {
            Node* temp = head;
            if(temp == nullptr) {
                cout << "List is empty!" << endl;
            }
            else {
                while(temp != nullptr) {
                    cout << temp->data << " ";
                    temp = temp->next;
                }
                cout << endl;
            }
        }

        //Get the size of the list
        int getSize() {
            return size;
        }
};

int main() {
    LinkedList myList;

    myList.insertAtBeginning(2);
    myList.insertAtEnd(3);
    myList.insertAtBeginning(1);
    myList.insertAtPosition(2,2);
    myList.traverseList(); //Expected output: 1 2 2 3

    myList.deleteNode(2);
    myList.traverseList(); //Expected output: 1 2 3

    cout << "Size of the list: " << myList.getSize() << endl; //Expected output: 3

    return 0;
}
```

In this implementation, the `Node` struct is used to represent each individual node in the linked list. It contains the data stored in the node and a pointer to the next node in the list.

The `LinkedList` class is used to manage the linked list. It contains private data members such as a pointer to the start of the list and the size of the list. The public member functions provide operations such as inserting nodes at the beginning, end or at a specific position in the list, deleting nodes, traversing the entire list, and getting the size of the list.

