 * @param {number} num - The positive integer to calculate the factorial for.
 * @returns {number|string} - The calculated factorial value, or an error message if input is invalid.
 */
function factorial(num) {
  if (typeof num !== "number" || num < 0 || num % 1 !== 0) {
    return "Invalid input. Please enter a positive integer.";
  }
  let result = 1;
  for (let I = 2; I <= num; i++) {
    result *= i;
  }
  return result;
