// Recursive function to calculate the factorial of a given number
int factorial(int n) {
    if(n < 0) {
        cerr << "Error: Factorial of negative number is undefined." << endl;
        return -1;
    }
    if(n == 0) {
        return 1;
    }
    return n * factorial(n-1);
}

