Next, we define functions for each of the basic matrix operations:

```c
Matrix matrix_add(Matrix a, Matrix b) {
    Matrix result;
    if (a.rows != b.rows || a.cols != b.cols) {
        // Handle error: matrices are not compatible
        result.rows = result.cols = 0;
        return result;
    }
    result.rows = a.rows;
    result.cols = a.cols;
    for (int I = 0; I < a.rows; i++) {
        for (int j = 0; j < a.cols; j++) {
            result.data[i][j] = a.data[i][j] + b.data[i][j];
        }
    }
    return result;
}

Matrix matrix_subtract(Matrix a, Matrix b) {
    // Same as add, but with subtraction instead of addition
}

Matrix matrix_multiply(Matrix a, Matrix b) {
    Matrix result;
    if (a.cols != b.rows) {
        // Handle error: matrices are not compatible
        result.rows = result.cols = 0;
        return result;
    }
    result.rows = a.rows;
    result.cols = b.cols;
    for (int I = 0; I < a.rows; i++) {
        for (int j = 0; j < b.cols; j++) {
            double sum = 0;
            for (int k = 0; k < a.cols; k++) {
                sum += a.data[i][k] * b.data[k][j];
            }
            result.data[i][j] = sum;
        }
    }
    return result;
}

Matrix matrix_scalar_multiply(Matrix a, double scalar) {
    Matrix result = a;
    for (int I = 0; I < a.rows; i++) {
        for (int j = 0; j < a.cols; j++) {
            result.data[i][j] *= scalar;
        }
    }
    return result;
}

Matrix matrix_transpose(Matrix a) {
    Matrix result;
    result.rows = a.cols;
    result.cols = a.rows;
    for (int I = 0; I < a.rows; i++) {
        for (int j = 0; j < a.cols; j++) {
            result.data[j][i] = a.data[i][j];
        }
    }
    return result;
}

Matrix matrix_inverse(Matrix a) {
